UPDATE companies SET description='Based in Algodones, New Mexico, Andy Sanchez Furniture has been crafting heirloom pieces for nearly three decades.

The workshop produces live-edge tables, chairs, and artistic furnishings that integrate precious stones and metals into exotic woods such as black walnut, alligator juniper, and eucalyptus. Rather than imposing a design on the material, the Sanchez team lets each slab’s natural contours guide the form, often employing book-matched cuts sourced from dead-standing timber in the Gila National Forest. Every piece is built through a collaborative, iterative process with the client, including photo updates and dimensional guidance.

The company serves residential clients and collectors seeking one-of-a-kind furniture tailored to specific spaces and stories. Customers range from homeowners commissioning dining tables to designers looking for narrative-rich objets d’art; each project begins with a conversation about the client’s vision and the wood’s inherent character.

The Sanchez philosophy centers on preserving nature’s integrity: they use only well-cured dead-standing or reclaimed wood, frequently pair stones from the same locale as the timber, and guarantee satisfaction by refining designs until the piece tells the client’s story. This wood-led approach, combined with multi-generational artistry, distinguishes their work in the custom furniture market.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture design", "Live-edge woodworking", "Stone and gem inlay", "Metal integration", "Book matching", "Reclaimed wood sourcing", "Client collaborative design iteration", "Dimensional planning assistance"], "industries": ["Residential furniture", "Custom furniture", "Art furniture", "Interior design"], "materials": ["Black walnut", "Alligator juniper", "Eucalyptus", "Exotic woods", "Dead-standing wood", "Reclaimed wood", "Precious stones", "Gems", "Metals"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Wood-led design process guided by each slab\u2019s natural contours", "Dead-standing timber sourced from Gila National Forest", "Book-matched cuts from hand-selected logs", "Stones often sourced from same location as the wood", "Iterative client collaboration with photo updates until satisfaction"], "facts_used": ["Location: Algodones, New Mexico -> db", "Family-owned, founded by Andy Sanchez with sons Aaron and Daniel, wife Cheryl -> /about-us", "Nearly 30 years of operation -> /about-us", "Live-edge furniture with stone/gem inlay -> /", "Exotic woods: black walnut, alligator juniper, eucalyptus -> /", "Wood-led design process, book matching -> /about-us", "Dead-standing wood from Gila National Forest -> /about-us", "Reclaimed wood sourcing from landscapers -> /about-us", "Iterative client collaboration with photo updates -> /about-us", "Serves residential clients and collectors -> /", "Guarantee satisfaction through design iteration -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "In the shop, Andy and his sons design the furniture based off of your needs.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='andy-sanchez-furniture' AND approved AND profile IS NULL;
UPDATE companies SET description='Apex Wire Products Co., Inc. was founded in 1940 in Franklin Park, Illinois, a suburb of Chicago. The company has operated continuously from this location for over 80 years, building a reputation for precision wire forming and metal fabrication.

The company specializes in CNC wire forming, custom welding, wire straightening and cutting, swaging, piercing, brazing, and threading. Its Franklin Park facility runs multi-axis CNC equipment capable of forming wire diameters from 0.015 to 0.472 inches in materials such as stainless steel, low-carbon steel, spring steel, copper alloys, and specialty grades. Wire straightening and cutting handles diameters up to 0.750 inches. The shop supports both prototype and high-volume production runs, with in-house tooling and fixture design enabling rapid changeovers and complete traceability at every stage.

Apex serves a range of industries including lighting fixtures (joist brackets), hot beverage equipment (coffee baskets), educational products (horizon cradles), transportation (bent bolts, U-bolts), medical devices (surgical instruments, orthopedic implants), food processing, automotive, and rail. Customers rely on the company for consistent, durable wire components that integrate into larger assemblies.

It differentiates itself by keeping all fabrication, joining, and finishing operations under one roof, which reduces lead times and simplifies supply chains. Apex’s stated goal is complete production and assembly from blueprint to on-time delivery, backed by traceable documentation and rigorous inspection.', certifications=ARRAY[]::text[], profile='{"capabilities": ["CNC wire forming (multi-axis)", "Custom welding (MIG, TIG, resistance, silver soldering)", "Wire straightening and cutting", "Swaging", "Piercing", "Metal brazing", "Metal threading (standard and custom)", "Subassembly", "Secondary finishing", "Quality inspection and traceability", "Prototyping", "High-volume production", "Tooling and fixture design", "Press brake forming"], "industries": ["Lighting fixtures", "Hot beverage equipment", "Educational products", "Transportation", "Medical devices", "Food processing", "Automotive", "Rail"], "materials": ["Stainless steel", "Low-carbon steel", "Spring steel", "Copper alloys", "Specialty grades", "Aluminum", "All industrial and specialty metals"], "equipment": ["Multi-axis CNC wire forming machines", "Wire straightening and cutting equipment", "Swaging and piercing equipment", "MIG/TIG/resistance welding equipment", "Press brake"], "volume": "Prototype to high-volume production", "lead_time": "", "tolerances": "Wire straightening \u00b10.001 in; CNC forming holds precise tolerances", "built_on": ["In-house tooling and fixture design for rapid adjustments", "Complete production and assembly from blueprint to on-time delivery", "Traceable documentation at every production stage", "Wire straightening tolerance of \u00b10.001 inches", "Multi-axis CNC forming for complex, multi-plane geometries"], "facts_used": ["Founded 1940 in Franklin Park, Illinois -> db (founded_year, hq_city, hq_state_label) and home page ''Since 1940''", "Specializes in CNC wire forming, custom welding, wire straightening & cutting -> db description and home page", "Wire diameters 0.015\u20130.472 in for forming, up to 0.750 in for straightening -> home page", "Materials: stainless, low carbon, spring steel, copper alloys, specialty grades -> home page", "Prototyping to high-volume runs -> home page", "In-house tooling and fixture design -> home page", "MIG, TIG, resistance welding, silver soldering -> home page and services page", "Wire straightening tolerance \u00b10.001 in -> services page", "Industries: lighting, hot beverage, educational, transportation, medical, food, automotive, rail -> home page project gallery and industries_served", "ISO certifications mentioned -> home page", "Team members: Matthew Kosowski (GM), Ryan Harmon (Office Manager), Carl Kosowski (Sales Manager) -> about-us page", "Quick turnaround and customer service emphasized -> home page"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Apex Wire Products Co., Inc. Specializes in CNC Wire Forming, Custom Welding, and Wire Straightening & Cutting Services", "founded_year": "1940", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='apex-wire-products-co-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Apocalypse Design Inc. was founded in 1983 in Fairbanks, Alaska, by Dick Flaharty, who named the company after the unclimbed 9,000-foot Apocalypse peak in the remote Revelation Mountains.

The company designs and sews every piece of its rugged outdoor apparel and gear in its Fairbanks facility. Its product line includes expedition parkas, anoraks, wind jackets and bibs, fleece layers, hats, and a range of packs, duffels, and accessories. Apocalypse Design also offers custom manufacturing, selecting materials and tailoring designs for extreme arctic conditions.

The company emphasizes a lifetime warranty against defects in materials and workmanship, reflecting a focus on durability for the harshest environments.

